package com.agriconnect.analytics; import java.time.Duration; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.context.annotation.*; import org.springframework.http.client.SimpleClientHttpRequestFactory; import org.springframework.web.client.RestClient;
@SpringBootApplication public class AnalyticsApplication { public static void main(String[]a){SpringApplication.run(AnalyticsApplication.class,a);} @Bean RestClient core(@Value("${core.url}")String url){var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(Duration.ofSeconds(3));f.setReadTimeout(Duration.ofSeconds(10));return RestClient.builder().baseUrl(url).requestFactory(f).build();} }
